using Educatinal_Platform.DTOs;
using Educatinal_Platform.Exceptions;
using Educatinal_Platform.Models;
using Educatinal_Platform.Repositories;
namespace Educatinal_Platform.Services;
public interface IStudentReviewService { Task<List<StudentReviewDto>> GetAllAsync(); Task<StudentReviewDto> CreateAsync(StudentReviewUpsertDto dto); Task<StudentReviewDto> UpdateAsync(string id, StudentReviewUpsertDto dto); Task DeleteAsync(string id); }
public class StudentReviewService(IStudentReviewRepository repository) : IStudentReviewService { public async Task<List<StudentReviewDto>> GetAllAsync() => (await repository.GetAllAsync()).Select(Map).ToList(); public async Task<StudentReviewDto> CreateAsync(StudentReviewUpsertDto dto) { Validate(dto); var item = Apply(new StudentReview(), dto); await repository.CreateAsync(item); return Map(item); } public async Task<StudentReviewDto> UpdateAsync(string id, StudentReviewUpsertDto dto) { Validate(dto); var item = await repository.GetByIdAsync(id) ?? throw new NotFoundException("Student review not found."); Apply(item, dto); item.UpdatedAt = DateTime.UtcNow; await repository.ReplaceAsync(item); return Map(item); } public async Task DeleteAsync(string id) { if (await repository.GetByIdAsync(id) is null) throw new NotFoundException("Student review not found."); await repository.DeleteAsync(id); } private static StudentReview Apply(StudentReview x, StudentReviewUpsertDto d) { x.Name=d.Name.Trim(); x.Initials=d.Initials.Trim().ToUpperInvariant(); x.Rating=d.Rating; x.ReviewText=d.ReviewText.Trim(); return x; } private static void Validate(StudentReviewUpsertDto d) { if (string.IsNullOrWhiteSpace(d.Name)||d.Name.Trim().Length>100) throw new BadRequestException("Name is required and must be 100 characters or fewer."); if (string.IsNullOrWhiteSpace(d.Initials)||d.Initials.Trim().Length>8) throw new BadRequestException("Initials are required and must be 8 characters or fewer."); if (d.Rating is < 1 or > 5) throw new BadRequestException("Rating must be between 1 and 5."); if (string.IsNullOrWhiteSpace(d.ReviewText)||d.ReviewText.Trim().Length>1500) throw new BadRequestException("Review text is required and must be 1500 characters or fewer."); } private static StudentReviewDto Map(StudentReview x) => new() { Id=x.Id,Name=x.Name,Initials=x.Initials,Rating=x.Rating,ReviewText=x.ReviewText,CreatedAt=x.CreatedAt,UpdatedAt=x.UpdatedAt }; }
